14	/// A fork frame pushed when FSPLIT bifurcates execution.
15	/// Tracks the two parallel branches until FFUSE joins them.
16	#[derive(Copy, Clone)]
17	struct ForkFrame {
18	    /// Position just after the matching FFUSE (where to resume after join).
19	    resume_ip: usize,
20	    /// The value carried on the right branch (gated by EVALT/EVALF).
21	    right_val: B4,
22	    /// Whether the right branch has been populated.
23	    right_set: bool,
24	}
