63	    /// The ⊥ mirror: exchange the R1 (O_∞) and R2 (O_inf_dag) evidence triples,
64	    /// role for role, leaving the shared substrate (self_ref, frobenius_order,
65	    /// period, value_period, sig, diversity) untouched — the two dialects sit on
66	    /// one temporal substrate; only the evidence changes hands:
67	    ///   static mark:   dialetheia_complete      ↔ atomic_reentry
68	    ///   counted act:   b_live_ticks             ↔ winding_count
69	    ///   recurrence:    gate_discriminations > 0 ↔ bifurcation_revisited
70	    /// The count↔bool leg passes through the canonical section (true ↦ 1),
71	    /// so mirrored() alone is involutive on the witness plane, not on raw
72	    /// counts. The exact involution is Kernel::arev_hop, which is parity over
73	    /// unchanged accumulators — the door, not the mirror.
74	    pub fn mirrored(self) -> Snapshot {
75	        let mut m = self;
76	        m.dialetheia_complete = self.atomic_reentry;
77	        m.atomic_reentry      = self.dialetheia_complete;
78	        m.b_live_ticks        = self.winding_count as u64;
79	        m.winding_count       = self.b_live_ticks.min(u32::MAX as u64) as u32;
80	        m.gate_discriminations   = if self.bifurcation_revisited { 1 } else { 0 };
81	        m.bifurcation_revisited  = self.gate_discriminations > 0;
82	        m.tier = compute_tier(&m);
83	        m
84	    }
85	}
