87	/// Graph-execution kernel.
88	/// FSPLIT creates fork frames. FFUSE joins them.
89	/// Program is inherently cyclic: end wraps to start.
90	/// TANCH at root depth sinks the wire -> halt.
91	pub struct Kernel {
92	    pub program:     Program,
93	    pub ip:          usize,
94	    pub phase:       Phase,
95	    pub tick_count:  u64,
96	    pub memory:      B4Memory,
97	    pub stack:       B4Stack,
98	    pub registers:   B4Registers,
99	    pub snapshot:    Option<Snapshot>,
100	    pub frob_checks: u64,
101	    pub frob_open:   u64,
102	    pub harness:     FrobeniusHarness,
103	    fork_stack:      [ForkFrame; FORK_STACK_CAP],
104	    fork_depth:      usize,
105	    pub fork_overflow: u64,   // FSPLITs that exceeded FORK_STACK_CAP (0 in practice)
106	    pub halted:      bool,
107	    pub dynamic_mode: bool,  // true → rebuild program from IgTuple each wrap
108	    // ── Cross-dialect ruleset state ──
109	    pub active_dialect: u8,        // 0-87, current active ruleset (default 0 = canonical)
110	    /// ⊥ (chirality): false = or' reading (R1-dominant, the canonical hand),
111	    /// true = flipped — the kernel reads its own snapshot through the mirror
112	    /// (O_∞ ↔ O_inf_dag lateral hop, the ob3ect's AREV step 15). Toggled by
113	    /// arev_hop(); parity over unchanged accumulators, so hop∘hop = id exactly.
114	    pub chirality: bool,
115	    pub liminal_target: Option<u8>, // dialect jumped to, pending IFIX seal
116	    pub liminal_compound: Option<u8>,   // compound index (0-10) used for liminal jump
117	    // ── Runtime accumulators for dynamic snapshot fields ──
118	    b_live_count:             u64,
119	    gate_discrimination_count: u64,
120	    value_trace:              [B4; 16],   // ring buffer of stack-top values after each tick
121	    value_trace_head:         usize,
122	    winding_count:            u32,   // protected: incremented on every natural end-of-program
123	                                      // wrap, never reset (not even by disable_dynamic)
124	}
