243	    /// One Frobenius tick. Returns false if halted.
244	    pub fn tick(&mut self) -> bool {
245	        if self.phase == Phase::Halt || self.halted { return false; }
246	        self.tick_count += 1;
247	
248	        // THINK
249	        self.phase = Phase::Think;
250	        // ── Use dynamic_imscribe so tier reflects runtime behavior ──
251	        self.snapshot = Some(self.dynamic_imscribe());
252	        self.maybe_promote();
253	
254	        // ACT
255	        self.phase = Phase::Act;
256	        if self.ip >= self.program.len() {
257	            self.ip = 0;
258	            self.try_self_modify();
259	        }
260	        let tok = self.program.get(self.ip).unwrap();
261	
262	        let mut next_ip = self.ip + 1;
263	        if next_ip >= self.program.len() {
264	            next_ip = 0;
265	            // Natural full-program wrap — protected winding, never reset. FFUSE's
266	            // jump-to-resume below can also land next_ip at 0, but that's a fork
267	            // resume, not a completed pass, so it does not increment this.
268	            self.winding_count = self.winding_count.saturating_add(1);
269	        }
270	
271	        match tok {
272	            Token::Vinit => {
273	                self.stack.push(B4::N);
274	            }
275	            Token::Tanch => {
276	                let val = self.stack.pop();
277	                let addr = self.registers.read(0) as usize;
278	                self.memory.write(addr, val);
279	                if !self.in_fork() {
280	                    self.phase = Phase::Halt;
281	                    self.halted = true;
282	                    return false;
283	                }
284	            }
285	            Token::Afwd => {
286	                let r0 = self.registers.read(0) as u8;
287	                self.registers.write(0, B4::from_u8(r0.wrapping_add(1)));
288	            }
289	            Token::Arev => {
290	                let r0 = self.registers.read(0) as u8;
291	                self.registers.write(0, B4::from_u8(r0.wrapping_sub(1)));
292	            }
293	            Token::Clink => {
294	                let a = self.registers.read(1);
295	                let b = self.registers.read(2);
296	                self.registers.write(3, b4_meet(a, b));
297	            }
298	            Token::Imscrib => {
299	                if let Some(snap) = self.snapshot {
300	                    self.registers.write(4, B4::from_u8(snap.token_diversity as u8 & 3));
301	                    self.registers.write(5, if snap.self_ref           { B4::T } else { B4::F });
302	                    self.registers.write(6, if snap.frobenius_order > 0 { B4::T } else { B4::F });
303	                    self.registers.write(7, if snap.dialetheia_complete { B4::T } else { B4::F });
304	                }
305	            }
306	            Token::Fsplit => {
307	                let v = self.stack.peek();
308	                let ffuse_ip = self.find_matching_ffuse(self.ip);
309	                let resume = if ffuse_ip + 1 >= self.program.len() { 0 }
310	                             else { ffuse_ip + 1 };
311	                self.push_fork(resume);
312	                if let Some(frame) = self.fork_top_mut() {
313	                    frame.right_val = v;
314	                    frame.right_set = true;
315	                }
316	                self.stack.push(v);
317	            }
318	            Token::Evalt => {
319	                let v = self.stack.pop();
320	                // ── B-live instrumentation: B on stack when gate fires ──
321	                if v == B4::B { self.b_live_count += 1; }
322	                let filtered = if v == B4::T { B4::T } else { B4::N };
323	                // ── Gate discrimination: T actually passed ──
324	                if v == B4::T { self.gate_discrimination_count += 1; }
325	                self.stack.push(filtered);
326	            }
327	            Token::Evalf => {
328	                let v = self.stack.pop();
329	                // ── B-live instrumentation ──
330	                if v == B4::B { self.b_live_count += 1; }
331	                let filtered = if v == B4::F { B4::F } else { B4::N };
332	                // ── Gate discrimination: F actually passed ──
333	                if v == B4::F { self.gate_discrimination_count += 1; }
334	                self.stack.push(filtered);
335	            }
336	            Token::Ffuse => {
337	                let left = self.stack.pop();
338	                if let Some(frame) = self.pop_fork() {
339	                    let right = if frame.right_set { frame.right_val } else { B4::N };
340	                    self.stack.push(b4_join(left, right));
341	                    next_ip = frame.resume_ip;
342	                } else {
343	                    self.stack.push(left);
344	                }
345	            }
346	            Token::Engagr => {
347	                self.registers.engagr = true;
348	                self.stack.push(B4::B);
349	            }
350	            Token::Ifix => {
351	                let addr = self.registers.read(0) as usize;
352	                let val  = self.stack.pop();
353	                self.memory.write(addr, val);
354	            }
355	            Token::Fsplit3 => {
356	                // 3-way fork (T/F/I arms). In B4 context, same as Fsplit.
357	                let v = self.stack.peek();
358	                let ffuse_ip = self.find_matching_ffuse3(self.ip);
359	                let resume = if ffuse_ip + 1 >= self.program.len() { 0 }
360	                             else { ffuse_ip + 1 };
361	                self.push_fork(resume);
362	                if let Some(frame) = self.fork_top_mut() {
363	                    frame.right_val = v;
364	                    frame.right_set = true;
365	                }
366	                self.stack.push(v);
367	            }
368	            Token::Ffuse3 => {
369	                // 3-way fuse. In B4 context, same as Ffuse.
370	                let left = self.stack.pop();
371	                if let Some(frame) = self.pop_fork() {
372	                    let right = if frame.right_set { frame.right_val } else { B4::N };
373	                    self.stack.push(b4_join(left, right));
374	                    next_ip = frame.resume_ip;
375	                } else {
376	                    self.stack.push(left);
377	                }
378	            }
379	            Token::Evali => {
380	                // Evaluate on Information axis: keep B (both), everything else -> N.
381	                let v = self.stack.pop();
382	                self.stack.push(if v == B4::B { B4::B } else { B4::N });
383	            }
384	            Token::Rotat => {
385	                // ROTAT — the first op-opcode: cyclic shift of the program-ring
386	                // by k, here realized as stack rotation. Pops k (default 1) and
387	                // rotates the remaining stack data by k positions mod depth.
388	                // The ring automorphism: ROTAT^n = identity.
389	                let k_val = self.stack.pop();
390	                let k = (k_val as u8 as usize).max(1);
391	                self.stack.rotate(k);
392	            }
393	        }
394	
395	        self.ip = next_ip;
396	
397	        // ── Write stack-top value into ring buffer (end of ACT) ──
398	        self.value_trace[self.value_trace_head] = self.stack.peek();
399	        self.value_trace_head = (self.value_trace_head + 1) % 16;
400	
401	        // OBSERVE
402	        self.phase = Phase::Observe;
403	        self.frob_checks += 1;
404	        // ── Frobenius harness verification ──
405	        { use crate::frob_verify::{verify_program_structure, verify_frobenius_identity}; 
406	          let _ = self.harness.check(verify_program_structure(&self.program)); 
407	          let v = self.stack.peek(); 
408	          let _ = self.harness.check(verify_frobenius_identity(v)); 
409	          self.frob_checks = self.harness.total(); 
410	          self.frob_open   = self.harness.open_count; }
411	
412	        // UPDATE
413	        self.phase = Phase::Update;
414	        if self.ip >= self.program.len() {
415	            self.ip = 0;
416	            self.try_self_modify();
417	        }
418	
419	        self.phase = Phase::Think;
420	        true
421	    }
