526	    fn maybe_promote(&mut self) {
527	        if let Some(snap) = self.snapshot {
528	            let old = snap.tier;
529	            let new = compute_tier(&snap);
530	            if new != old {
531	                if let Some(s) = self.snapshot.as_mut() { s.tier = new; }
532	            }
533	        }
534	    }
