```rust
// ── the gate, on-board ────────────────────────────────────────────
let has_tri = word.chars().any(|c| matches!(c, '∈' | '∋' | '~' | '≁'));
let verdict = if has_tri {
    let steps = imasm16_3::parse_glyph_word(&word);
    let (v, _) = imasm16_3::tri_ancestral_verdict(&steps);
    v
